// 温暖纪实 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、dissolve()（慢叠化进出）、floating()（一段文字一层：叠化 + 极慢上移 + 整体推近）、spaced()（宋体加字距）、
// photo()（照片小样与纸边）、spotlight()（暗角收拢的高亮）、atmosphere()（暖调底、漏光、暗角）、grain()（胶片颗粒）、letterbox()（遮幅）。

const STYLE = {
  color: {
    top: "#2B211A",
    bottom: "#3F3025",
    leak: "255,190,120", // 漏光的 RGB，只改透明度
    text: "#F1E6D6",
    muted: "#B9A58C",
    accent: "#D9A066",
  },
  font: {
    serif: '"Source Han Serif SC", "Noto Serif SC", "Source Han Serif", "STZhongsong", "华文中宋", "SimSun", serif',
    number: '"Georgia", "Source Han Serif SC", "Noto Serif SC", serif',
  },
};

// 叠化交接：相邻两段重叠约 0.3 秒，旧的慢慢淡下去时新的已经浮上来。
const SCENES = { title: [0, 2.1], keyword: [1.8, 3.8], media: [3.5, 6.4], data: [6.1, 8.3], name: [8.0, 9.7], end: [9.4, 99] };
const COPY = {
  date: "二〇二六 · 秋",
  title: "把想法变成画面",
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const sineInOut = (v) => -(Math.cos(Math.PI * clamp(v)) - 1) / 2;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 慢叠化：进 0.8 s、出 0.5 s，同时有极慢的上移，像呼吸。返回 { a: 不透明度, dy: 位移系数 }。
function dissolve(t, [a, b], delay = 0, inDur = 0.8, outDur = 0.5) {
  const enter = sineInOut((t - a - delay) / inDur), leave = sineInOut((t - (b - outDur)) / outDur);
  return { a: enter * (1 - leave), dy: 1 - enter + leave * 0.5, enter };
}

function spaced(ctx, text, x, y, tracking, align = "center") {
  const chars = [...text];
  const widths = chars.map((c) => ctx.measureText(c).width);
  const total = widths.reduce((s, v) => s + v, 0) + tracking * (chars.length - 1);
  let cx = align === "center" ? x - total / 2 : x;
  chars.forEach((c, i) => { ctx.fillText(c, cx, y); cx += widths[i] + tracking; });
  return total;
}

function atmosphere(ctx, t, w, h) {
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, STYLE.color.top);
  g.addColorStop(1, STYLE.color.bottom);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  // 漏光：一团暖光在画面右上缓慢游移，强弱随时间起伏。
  const lx = w * (0.72 + 0.08 * Math.sin(t * 0.5)), ly = h * (0.28 + 0.06 * Math.cos(t * 0.37));
  const strength = 0.2 + 0.06 * Math.sin(t * 0.9);
  const leak = ctx.createRadialGradient(lx, ly, 0, lx, ly, w * 0.55);
  leak.addColorStop(0, `rgba(${STYLE.color.leak},${strength})`);
  leak.addColorStop(1, `rgba(${STYLE.color.leak},0)`);
  ctx.fillStyle = leak;
  ctx.fillRect(0, 0, w, h);
  const v = ctx.createRadialGradient(w / 2, h / 2, h * 0.35, w / 2, h / 2, w * 0.7);
  v.addColorStop(0, "rgba(10,6,3,0)");
  v.addColorStop(1, "rgba(10,6,3,0.6)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, w, h);
}

let grainCanvas = null;
function grain(ctx, t, w, h) {
  if (!grainCanvas) {
    grainCanvas = new OffscreenCanvas(1, 1);
    grainCanvas.width = grainCanvas.height = 256;
    const g = grainCanvas.getContext("2d"), img = g.createImageData(256, 256);
    let s = 11;
    for (let i = 0; i < img.data.length; i += 4) {
      s = (s * 16807) % 2147483647;
      const v = (s / 2147483647) * 255;
      img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
      img.data[i + 3] = 255;
    }
    g.putImageData(img, 0, 0);
  }
  const f = Math.floor(t * 24);
  ctx.save();
  ctx.globalAlpha = 0.09;
  ctx.globalCompositeOperation = "overlay";
  ctx.fillStyle = ctx.createPattern(grainCanvas, "repeat");
  ctx.translate((f * 97) % 256, (f * 61) % 256);
  ctx.fillRect(-256, -256, w + 512, h + 512);
  ctx.restore();
}

function letterbox(ctx, w, h) {
  const bar = h * 0.085;
  ctx.fillStyle = "#0B0806";
  ctx.fillRect(0, 0, w, bar);
  ctx.fillRect(0, h - bar, w, bar);
}

// 整体极慢推近：每秒约放大 0.4%，给静态画面一点镜头感。围绕画面中心缩放。
const zoomAt = (t) => 1 + 0.004 * t;

// 一段内容一层：内容在画面坐标里画；pose = 先上浮 rise·dy，再绕画面中心推近，不透明度跟随叠化。
function floating(w, h, { bounds, scene, delay = 0, inDur = 0.8, outDur = 0.5, rise, draw }) {
  return {
    bounds,
    pose: (t) => {
      const d = dissolve(t, scene, delay, inDur, outDur), z = zoomAt(t);
      if (d.a <= 0) return null;
      return { x: (w / 2) * (1 - z), y: (h / 2) * (1 - z) - z * d.dy * rise, scale: z, opacity: d.a };
    },
    draw,
  };
}

// 照片小样：傍晚的山野与一间亮着灯的小屋（示意），奶白纸边像一张冲洗出来的照片；
// k 是照片里的慢推（Ken Burns），在纸边里面进行。目标是小屋亮灯的窗。
function photoTarget(px, py, pw, ph) { return { x: px + pw * 0.62, y: py + ph * 0.66, r: ph * 0.16 }; }
function photo(ctx, px, py, pw, ph, k, u) {
  const m = 10 * u;
  ctx.fillStyle = "#E9DCC7"; ctx.fillRect(px - m, py - m, pw + 2 * m, ph + 2 * m);
  ctx.save(); ctx.beginPath(); ctx.rect(px, py, pw, ph); ctx.clip();
  const s = 1 + 0.05 * k, cx = px + pw * 0.62, cy = py + ph * 0.62;
  ctx.translate(cx, cy); ctx.scale(s, s); ctx.translate(-cx, -cy);
  const sky = ctx.createLinearGradient(0, py, 0, py + ph * 0.7);
  sky.addColorStop(0, "#5A4636"); sky.addColorStop(0.7, "#C98E5A"); sky.addColorStop(1, "#E3B07A");
  ctx.fillStyle = sky; ctx.fillRect(px, py, pw, ph);
  const sun = ctx.createRadialGradient(px + pw * 0.3, py + ph * 0.6, 0, px + pw * 0.3, py + ph * 0.6, ph * 0.3);
  sun.addColorStop(0, "rgba(255,226,170,0.9)"); sun.addColorStop(1, "rgba(255,226,170,0)");
  ctx.fillStyle = sun; ctx.fillRect(px, py, pw, ph);
  const hill = (kk, color, lift, amp) => {
    ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(px, py + ph);
    for (let i = 0; i <= 12; i++) ctx.lineTo(px + (pw * i) / 12, py + ph * (lift - amp * Math.sin(i * 0.9 + kk)));
    ctx.lineTo(px + pw, py + ph); ctx.closePath(); ctx.fill();
  };
  hill(0.6, "#6B4A34", 0.62, 0.06); hill(2.4, "#3E2B1F", 0.74, 0.05);
  // 小屋与亮灯的窗
  const T = photoTarget(px, py, pw, ph), hx = T.x - ph * 0.07, hy = py + ph * 0.6, hw = ph * 0.2, hh = ph * 0.14;
  ctx.fillStyle = "#24180F"; ctx.fillRect(hx, hy, hw, hh);
  ctx.beginPath(); ctx.moveTo(hx - ph * 0.02, hy); ctx.lineTo(hx + hw / 2, hy - ph * 0.08); ctx.lineTo(hx + hw + ph * 0.02, hy); ctx.closePath(); ctx.fill();
  const glow = ctx.createRadialGradient(T.x, T.y, 0, T.x, T.y, ph * 0.12);
  glow.addColorStop(0, "rgba(255,200,120,0.55)"); glow.addColorStop(1, "rgba(255,200,120,0)");
  ctx.fillStyle = glow; ctx.fillRect(T.x - ph * 0.12, T.y - ph * 0.12, ph * 0.24, ph * 0.24);
  ctx.fillStyle = "#FFD08A"; ctx.fillRect(T.x - ph * 0.025, T.y - ph * 0.03, ph * 0.05, ph * 0.05);
  hill(4.1, "#20160F", 0.9, 0.04);
  ctx.restore();
}

// 高亮：不加框，暗角向目标慢慢收拢，目标附近保持原亮度（像屋里的一盏灯）。k 0→1。
function spotlight(ctx, px, py, pw, ph, T, k) {
  if (k <= 0) return;
  ctx.save(); ctx.beginPath(); ctx.rect(px, py, pw, ph); ctx.clip();
  const g = ctx.createRadialGradient(T.x, T.y, T.r * 0.6, T.x, T.y, T.r * 4);
  g.addColorStop(0, "rgba(20,12,6,0)");
  g.addColorStop(1, `rgba(20,12,6,${0.62 * k})`);
  ctx.fillStyle = g; ctx.fillRect(px, py, pw, ph);
  ctx.restore();
}

function layers(_params, w, h) {
  const u = h / 720, C = STYLE.color, F = STYLE.font, out = [];
  // 底：暖调渐变、游移漏光、暗角，跟着整体推近。
  out.push({
    draw: (ctx, t) => {
      const z = zoomAt(t);
      ctx.save();
      ctx.translate(w / 2, h / 2); ctx.scale(z, z); ctx.translate(-w / 2, -h / 2);
      atmosphere(ctx, t, w, h);
      ctx.restore();
    },
  });
  const band = (y, size) => [w * 0.15, y - size * 1.2, w * 0.85, y + size * 0.5];

  // 标题（章节标题）：琥珀色日期先浮现，宋体标题随后，下方一段琥珀色短线慢慢展开托住它。不加副标题。
  const title = SCENES.title;
  out.push(floating(w, h, { bounds: band(h * 0.38, 16 * u), scene: title, rise: 8 * u, draw: (ctx) => {
    ctx.fillStyle = C.accent; ctx.font = font(400, 16 * u, F.serif); spaced(ctx, COPY.date, w / 2, h * 0.38, 8 * u);
  } }));
  out.push(floating(w, h, { bounds: band(h * 0.54, 60 * u), scene: title, delay: 0.2, rise: 10 * u, draw: (ctx) => {
    ctx.fillStyle = C.text; ctx.font = font(500, 60 * u, F.serif); spaced(ctx, COPY.title, w / 2, h * 0.54, 10 * u);
  } }));
  out.push(floating(w, h, { bounds: [w / 2 - 40 * u, h * 0.62 - 4 * u, w / 2 + 40 * u, h * 0.62 + 4 * u], scene: title, delay: 0.45, rise: 4 * u, draw: (ctx, t) => {
    const k = sineInOut((t - 0.5) / 0.9);
    ctx.fillStyle = C.accent; ctx.fillRect(w / 2 - 28 * u * k, h * 0.62, 56 * u * k, Math.max(1, u));
  } }));

  // 花字与关键词：不加粗、不换大色块。“风格”小而淡，“不走样”宋体放大一档；文字浮现后，下方琥珀色细线慢慢划过“不走样”。
  const kw = SCENES.keyword, ky = h * 0.55;
  out.push(floating(w, h, { bounds: [w * 0.2, ky - 90 * u, w * 0.8, ky + 30 * u], scene: kw, rise: 10 * u, draw: (ctx, t) => {
    ctx.font = font(400, 30 * u, F.serif);
    const leadW = [...COPY.keyword.lead].reduce((s, c) => s + ctx.measureText(c).width, 0) + 8 * u * (COPY.keyword.lead.length - 1);
    ctx.font = font(500, 76 * u, F.serif);
    const keyW = [...COPY.keyword.key].reduce((s, c) => s + ctx.measureText(c).width, 0) + 14 * u * (COPY.keyword.key.length - 1);
    const x0 = w / 2 - (leadW + 28 * u + keyW) / 2;
    ctx.fillStyle = C.muted; ctx.font = font(400, 30 * u, F.serif); spaced(ctx, COPY.keyword.lead, x0, ky, 8 * u, "left");
    ctx.fillStyle = C.text; ctx.font = font(500, 76 * u, F.serif); spaced(ctx, COPY.keyword.key, x0 + leadW + 28 * u, ky, 14 * u, "left");
    const k = sineInOut((t - kw[0] - 0.7) / 0.9);
    if (k > 0) { ctx.fillStyle = C.accent; ctx.fillRect(x0 + leadW + 28 * u, ky + 20 * u, keyW * k, Math.max(1, 1.5 * u)); }
  } }));

  // 图片与录屏容器 + 高亮：照片带奶白纸边叠化浮现，照片里一直在极慢地推近；下方一行小字标明“示意画面”。
  // 高亮：暗角向小屋亮灯的窗慢慢收拢（约 0.9 s），不加框。
  const media = SCENES.media, pw = w * 0.5, ph = pw * 0.62, px = (w - pw) / 2, py = h * 0.47 - ph / 2, T = photoTarget(px, py, pw, ph);
  out.push(floating(w, h, { bounds: [px - 12 * u, py - 12 * u, px + pw + 12 * u, py + ph + 12 * u], scene: media, inDur: 0.9, rise: 10 * u, draw: (ctx, t) => {
    photo(ctx, px, py, pw, ph, clamp((t - media[0]) / (media[1] - media[0])), u);
    spotlight(ctx, px, py, pw, ph, T, sineInOut((t - media[0] - 1.3) / 0.9));
  } }));
  out.push(floating(w, h, { bounds: [w * 0.3, py + ph + 24 * u, w * 0.7, py + ph + 60 * u], scene: media, delay: 0.35, rise: 6 * u, draw: (ctx) => {
    ctx.fillStyle = C.muted; ctx.font = font(400, 16 * u, F.serif); spaced(ctx, COPY.media, w / 2, py + ph + 48 * u, 6 * u);
  } }));

  // 数据：Georgia 大数字慢慢计数（sineInOut，慢慢停下）；短线和说明随后浮现。
  const data = SCENES.data;
  out.push(floating(w, h, { bounds: [w * 0.3, h * 0.55 - 130 * u, w * 0.7, h * 0.55 + 40 * u], scene: data, rise: 10 * u, draw: (ctx, t) => {
    const n = Math.round(COPY.data.value * sineInOut((t - data[0] - 0.1) / 1.2));
    ctx.fillStyle = C.text; ctx.font = font(400, 150 * u, F.number); ctx.textAlign = "center";
    const nw = ctx.measureText(`${n}`).width;
    ctx.fillText(`${n}`, w / 2 - 18 * u, h * 0.55);
    ctx.font = font(400, 48 * u, F.number); ctx.textAlign = "left";
    ctx.fillText(COPY.data.unit, w / 2 - 18 * u + nw / 2 + 6 * u, h * 0.55);
  } }));
  out.push(floating(w, h, { bounds: [w * 0.3, h * 0.62 - 4 * u, w * 0.7, h * 0.68 + 12 * u], scene: data, delay: 0.35, rise: 6 * u, draw: (ctx) => {
    ctx.fillStyle = C.accent; ctx.fillRect(w / 2 - 24 * u, h * 0.62, 48 * u, Math.max(1, u));
    ctx.fillStyle = C.muted; ctx.font = font(400, 20 * u, F.serif); spaced(ctx, COPY.data.label, w / 2, h * 0.68, 8 * u);
  } }));

  // 人名条：左下一行，名字 + 琥珀色竖线 + 职位，不加底板。
  const name = SCENES.name, nx = w * 0.1, ny = h * 0.78;
  out.push(floating(w, h, { bounds: [nx - 10 * u, ny - 40 * u, nx + 360 * u, ny + 14 * u], scene: name, delay: 0.1, inDur: 0.8, outDur: 0.5, rise: 6 * u, draw: (ctx) => {
    ctx.fillStyle = C.text; ctx.font = font(500, 30 * u, F.serif);
    const nw = spaced(ctx, COPY.name.name, nx, ny, 8 * u, "left");
    ctx.fillStyle = C.accent; ctx.fillRect(nx + nw + 22 * u, ny - 20 * u, Math.max(1, u), 24 * u);
    ctx.fillStyle = C.muted; ctx.font = font(400, 18 * u, F.serif);
    spaced(ctx, COPY.name.role, nx + nw + 44 * u, ny - 2 * u, 4 * u, "left");
  } }));

  // 收尾：一句话慢慢叠化出现，停留足够久。
  out.push(floating(w, h, { bounds: band(h * 0.53, 42 * u), scene: SCENES.end, delay: 0.1, inDur: 1.0, rise: 10 * u, draw: (ctx) => {
    ctx.fillStyle = C.text; ctx.font = font(500, 42 * u, F.serif); spaced(ctx, COPY.end, w / 2, h * 0.53, 10 * u);
  } }));

  // 最上面：胶片颗粒与遮幅，不随推近。
  out.push({ draw: (ctx, t) => { grain(ctx, t, w, h); letterbox(ctx, w, h); } });
  return out;
}

export default {
  name: "温暖纪实 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Warm Documentary · Sample",
  params: [],
  // 慢节奏也保留 180° 快门：动作慢时模糊自然很少，保持胶片的连贯感。
  motionBlur: { shutter: 180 },
  layers,
};
